pub fn analyze_binary_expression(expr: &Expr, target_binding: &str) -> Option<ArithmeticAnalysis> {
    let mut operations: Vec<Operation> = Vec::new();

    fn analyze(node: &Expr, target_binding: &str, operations: &mut Vec<Operation>) {
        if let Expr::Bin(bin_expr) = node {
            let left = &*bin_expr.left;
            let op = &bin_expr.op;
            let right = &*bin_expr.right;

            let left_is_target = is_binding_expression(left, target_binding);
            let right_is_target = is_binding_expression(right, target_binding);

            if left_is_target {
                if let Expr::Lit(Lit::Num(num)) = right {
                    operations.push(Operation {
                        op: op.clone(),
                        value: num.value,
                        side: "right".to_string(),
                    });
                    return;
                }
            }

            if right_is_target {
                if let Expr::Lit(Lit::Num(num)) = left {
                    operations.push(Operation {
                        op: op.clone(),
                        value: num.value,
                        side: "left".to_string(),
                    });
                    return;
                }
            }

            // Recurse
            analyze(left, target_binding, operations);
            analyze(right, target_binding, operations);
        }
    }

    analyze(expr, target_binding, &mut operations);

    if !operations.is_empty() {
        return Some(ArithmeticAnalysis {
            analysis_type: "arithmetic".to_string(),
            operations,
        });
    }

    None
}
